    terms: list[tuple[str, int]], compress_number_op: bool
) -> tuple[tuple[int, int, int], list[tuple[int, str]]]:
    """  # pylint: disable=missing-raises-doc
    pluses = set()
    minuses = set()
    numbers = set()
    facs = []
    for term in terms:
        if not term:
            continue
        c = term[0]
        i = int(term[1])
        if c == "+":
            pluses.add(i)
            facs.append((i, "+"))
        elif c == "-":
            if i in pluses:
                pluses.discard(i)
                numbers.add(i)
                if compress_number_op:
                    facs.remove((i, "+"))
                    facs.append((i, "N"))
                else:
                    facs.append((i, "-"))
            else:
                minuses.add(i)
                facs.append((i, "-"))
        else:
            raise ValueError("Unsupported operator ", c, " in term.")
    return (len(numbers), len(pluses), len(minuses)), facs

